def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 99:
        return 'D'
    my_ops, opp_ops = list(zip(*history))
    opp_c = opp_ops.count('C')
    opp_d = n - opp_c
    my_c = my_ops.count('C')
    my_d = n - my_c
    my_last, opp_last = history[-1]
    opp_rate = (opp_c + 1.0) / (n + 2.0)

    # Exploit opponent that never defects after we test them
    if opp_d == 0 and my_d > 0 and n > 8:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Initial probe: if opponent has been perfectly cooperative and we haven't defected yet,
    # test them with a defection once.
    if opp_d == 0 and my_d == 0 and n == 5:
        return 'D'

    # If opponent seems highly cooperative, mostly cooperate.
    if opp_rate >= 0.75:
        return 'C'

    # If opponent is mostly defecting, defect.
    if opp_rate <= 0.30:
        return 'D'

    # Medium cooperation: tit-for-tat with forgiveness.
    if opp_last == 'D':
        if opp_rate >= 0.55 and n >= 4:
            recent_opp = opp_ops[-4:]
            if recent_opp.count('D') <= 1 and rng.random() < 0.60:
                return 'C'
        return 'D'

    if my_last == 'D':
        return 'C'

    if opp_rate >= 0.55 and rng.random() < 0.10:
        return 'D'

    return 'C'
